function isHelpLikeToken(token) {
  if (token === '-h') {
    return true;
  }

  const help = '--help';

  if (token.length < 3) {
    return false;
  }

  if (token[0] !== '-' || token[1] !== '-') {
    return false;
  }

  if (token.length > help.length) {
    return false;
  }

  let index = 0;

  while (index < token.length) {
    if (token[index] !== help[index]) {
      return false;
    }

    index += 1;
  }

  return true;
}

function hasInlineAValue(token) {
  return token.length >= 4
    && token[0] === '-'
    && token[1] === '-'
    && token[2] === 'a'
    && token[3] === '=';
}

function startsWithDash(token) {
  return token.length > 0 && token[0] === '-';
}

export function analyzeArgv(argv) {
  let value;
  let sawA = false;
  let index = 0;

  while (index < argv.length) {
    const token = argv[index];

    if (isHelpLikeToken(token)) {
      return { mode: 'delegate' };
    }

    if (token === '--a') {
      const next = argv[index + 1];

      if (next === undefined) {
        return { mode: 'delegate' };
      }

      if (startsWithDash(next) && next !== '-') {
        return { mode: 'delegate' };
      }

      sawA = true;
      value = next;
      index += 2;
      continue;
    }

    if (hasInlineAValue(token)) {
      sawA = true;
      value = token.slice(4);
      index += 1;
      continue;
    }

    return { mode: 'delegate' };
  }

  if (!sawA) {
    return { mode: 'delegate' };
  }

  return { mode: 'normalized', value };
}

