import { analyzeArgv } from './cli/argv.mjs';
import {
  relayResult,
  runBackendWithArgs,
  runBackendWithValue,
} from './runtime/process_runner.mjs';

export function run(argv = process.argv.slice(2)) {
  const analysis = analyzeArgv(argv);
  const result = analysis.mode === 'normalized'
    ? runBackendWithValue(analysis.value)
    : runBackendWithArgs(argv);

  relayResult(result);
}

