import { spawnSync } from 'node:child_process';

import { PYTHON_BACKEND_PATH } from './constants.mjs';

function writeChunk(stream, chunk) {
  if (chunk && chunk.length > 0) {
    stream.write(chunk);
  }
}

export function runBackendWithArgs(args) {
  return spawnSync(PYTHON_BACKEND_PATH, args, {
    maxBuffer: 64 * 1024 * 1024,
    stdio: ['ignore', 'pipe', 'pipe'],
  });
}

export function runBackendWithValue(value) {
  return runBackendWithArgs(['--a', value]);
}

export function relayResult(result) {
  writeChunk(process.stdout, result.stdout);
  writeChunk(process.stderr, result.stderr);

  if (result.error) {
    const message = result.error.message ?? String(result.error);

    if (message.length > 0) {
      process.stderr.write(`${message}\n`);
    }

    process.exitCode = 1;
    return;
  }

  if (typeof result.status === 'number') {
    process.exitCode = result.status;
    return;
  }

  process.exitCode = 1;
}

