export function main(rawArgv = process.argv) {
  const programName = getProgramName(rawArgv);
  const parsed = parseCommandLine(rawArgv, programName);

  if (parsed.kind === 'help') {
    writeStdout(buildHelp(programName));
    return 0;
  }

  if (parsed.kind === 'error') {
    writeStderr(parsed.text);
    return parsed.exitCode;
  }

  const result = runYamlTransform(parsed.value);

  if (result.error) {
    throw result.error;
  }

  writeStdout(result.stdout);
  writeStderr(result.stderr);

  return result.status ?? 1;
}

