import { buildError } from './messages.mjs';

function isLongHelpOption(token) {
  return token.length > 2 && !token.includes('=') && '--help'.startsWith(token);
}

function isLongHelpWithExplicitArgument(token) {
  const separatorIndex = token.indexOf('=');

  if (separatorIndex === -1) {
    return false;
  }

  const option = token.slice(0, separatorIndex);

  return option.length > 2 && '--help'.startsWith(option);
}

function isShortHelpOption(token) {
  return token.startsWith('-h') && !token.startsWith('--');
}

function isOptionLike(token) {
  return token !== '-' && token.startsWith('-') && !isNegativeNumberLike(token);
}

export function parseCommandLine(rawArgv, programName) {
  const argumentsOnly = rawArgv.slice(2);
  const extras = [];
  let endOfOptions = false;
  let aValue;

  for (let index = 0; index < argumentsOnly.length; index += 1) {
    const token = argumentsOnly[index];

    if (endOfOptions) {
      extras.push(token);
      continue;
    }

    if (token === '--') {
      endOfOptions = true;
      continue;
    }

    if (isLongHelpWithExplicitArgument(token)) {
      return {
        kind: 'error',
        exitCode: ARGPARSE_ERROR_EXIT_CODE,
        text: buildError(programName, `argument -h/--help: ignored explicit argument '${token.slice(token.indexOf('=') + 1)}'`),
      };
    }

    if (isShortHelpOption(token) || isLongHelpOption(token)) {
      return { kind: 'help' };
    }

    if (token === '--a') {
      const nextToken = argumentsOnly[index + 1];

      if (nextToken === undefined || nextToken === '--' || isOptionLike(nextToken)) {
        return {
          kind: 'error',
          exitCode: ARGPARSE_ERROR_EXIT_CODE,
          text: buildError(programName, 'argument --a: expected one argument'),
        };
      }

      aValue = nextToken;
      index += 1;
      continue;
    }

    if (token.startsWith('--a=')) {
      aValue = token.slice(4);
      continue;
    }

    extras.push(token);
  }

  if (aValue === undefined) {
    return {
      kind: 'error',
      exitCode: ARGPARSE_ERROR_EXIT_CODE,
      text: buildError(programName, 'the following arguments are required: --a'),
    };
  }

  if (extras.length > 0) {
    return {
      kind: 'error',
      exitCode: ARGPARSE_ERROR_EXIT_CODE,
      text: buildError(programName, `unrecognized arguments: ${extras.join(' ')}`),
    };
  }

  return { kind: 'run', value: aValue };
}

