import { writeSync } from 'node:fs';

function writeChunk(fileDescriptor, chunk) {
  if (chunk === undefined || chunk === null) {
    return;
  }

  const buffer = Buffer.isBuffer(chunk) ? chunk : Buffer.from(String(chunk), 'utf8');

  if (buffer.length === 0) {
    return;
  }

  writeSync(fileDescriptor, buffer, 0, buffer.length);
}

export function writeStdout(chunk) {
  writeChunk(1, chunk);
}

export function writeStderr(chunk) {
  writeChunk(2, chunk);
}
